CREATE POLICY ml_direct_lead_update_gate ON public.sales_leads AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY ml_direct_lead_insert_gate ON public.sales_leads AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.is_admin());
CREATE POLICY ml_history_insert_gate ON public.sales_lead_history AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.is_admin());
CREATE POLICY ml_followup_insert_gate ON public.sales_followups AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.is_admin());
CREATE POLICY ml_followup_update_gate ON public.sales_followups AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY ml_offer_select ON public.offers FOR SELECT TO authenticated USING(payload->>'lead_id' IS NOT NULL AND public.ml_can_access((payload->>'lead_id')::uuid));
CREATE POLICY ml_offer_insert ON public.offers FOR INSERT TO authenticated WITH CHECK(payload->>'lead_id' IS NOT NULL AND public.ml_can_access((payload->>'lead_id')::uuid) AND created_by=auth.uid());
CREATE POLICY ml_offer_update ON public.offers FOR UPDATE TO authenticated USING(payload->>'lead_id' IS NOT NULL AND public.ml_can_access((payload->>'lead_id')::uuid) AND created_by=auth.uid()) WITH CHECK(payload->>'lead_id' IS NOT NULL AND public.ml_can_access((payload->>'lead_id')::uuid) AND created_by=auth.uid());
CREATE POLICY ml_customer_select ON public.customers FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.sales_leads l WHERE l.converted_customer_id=customers.id AND l.assigned_user=auth.uid() AND public.ml_can_access(l.id)));
CREATE OR REPLACE FUNCTION lead_private.ml_scoped_stats(_all boolean DEFAULT false,_tenant uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
 RETURN jsonb_build_object('open_offers',(SELECT count(*) FROM public.offers o WHERE coalesce(o.status,'draft') NOT IN ('order','signed','storniert','abgelehnt','expired','abgelaufen') AND EXISTS(SELECT 1 FROM public.sales_leads l WHERE public.ml_can_access(l.id) AND (l.assigned_user=auth.uid() OR (_all AND public.is_admin())) AND (_tenant IS NULL OR l.tenant_id=_tenant OR (public.is_admin() AND l.tenant_id IS NULL)) AND (o.id=l.converted_offer_id OR o.payload->>'lead_id'=l.id::text))),
 'order_value',(SELECT coalesce(sum(o.total_amount),0) FROM public.orders o WHERE EXISTS(SELECT 1 FROM public.sales_leads l JOIN public.offers f ON (f.id=l.converted_offer_id OR f.payload->>'lead_id'=l.id::text) WHERE public.ml_can_access(l.id) AND (l.assigned_user=auth.uid() OR (_all AND public.is_admin())) AND (_tenant IS NULL OR l.tenant_id=_tenant OR (public.is_admin() AND l.tenant_id IS NULL)) AND (o.raw_data->>'offer_number'=f.offer_number OR o.raw_data->>'source_offer'=f.offer_number OR o.raw_data->>'source_offer_number'=f.offer_number))),'orders',0); END $$;
REVOKE ALL ON FUNCTION lead_private.ml_scoped_stats(boolean,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION lead_private.ml_scoped_stats(boolean,uuid) TO authenticated;
CREATE FUNCTION public.ml_scoped_stats(_all boolean DEFAULT false,_tenant uuid DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT lead_private.ml_scoped_stats(_all,_tenant) $$;
REVOKE ALL ON FUNCTION public.ml_scoped_stats(boolean,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.ml_scoped_stats(boolean,uuid) TO authenticated;